class Solution {
    public int lengthLongestPath(String input) {
        String[] lines=input.split("\\n",-1);int[] lengths=new int[lines.length+1];int best=0;
        for(String line:lines){int d=0;while(d<line.length()&&line.charAt(d)=='\t')d++;String name=line.substring(d);
