class Solution {
    public boolean validUtf8(int[] data) {
        int i=0,n=data.length;
        while(i<n){int x=data[i];if(x<0||x>255)return false;int count;
            if((x>>7)==0)count=1;else if((x>>5)==0b110)count=2;else if((x>>4)==0b1110)count=3;else if((x>>3)==0b11110)count=4;else return false;
            if(i+count>n)return false;
            for(int j=i+1;j<i+count;j++)if(data[j]<0||data[j]>255||(data[j]>>6)!=0b10)return false;
            i+=count;
        }return true;
    }
}

class Solution:
    def decodeString(self, s: str) -> str:
        counts=[];strings=[];curr='';num=0
        for c in s:
            if c.isdigit():num=num*10+int(c)
            elif c=='[':
                counts.append(num);strings.append(curr);curr='';num=0
            elif c==']':
                curr=strings.pop()+curr*counts.pop()
            else:curr+=c
        return curr

import java.util.*;
class Solution {
    public String decodeString(String s) {
        Deque<Integer> counts=new ArrayDeque<>();Deque<StringBuilder> prefixes=new ArrayDeque<>();StringBuilder cur=new StringBuilder();int num=0;
        for(char c:s.toCharArray()){if(Character.isDigit(c))num=num*10+c-'0';else if(c=='['){counts.push(num);prefixes.push(cur);cur=new StringBuilder();num=0;}
            else if(c==']'){int k=counts.pop();StringBuilder prev=prefixes.pop();for(int i=0;i<k;i++)prev.append(cur);cur=prev;}else cur.append(c);}
        return cur.toString();
    }
}

from collections import Counter
class Solution:
    def longestSubstring(self, s: str, k: int) -> int:
        if len(s)<k:return 0
        counts=Counter(s)
        for c,n in counts.items():
            if n<k:
                return max((self.longestSubstring(part,k) for part in s.split(c)),default=0)
        return len(s)

class Solution {
    public int longestSubstring(String s,int k) {
        if(s.length()<k)return 0;int[]cnt=new int[26];for(char c:s.toCharArray())cnt[c-'a']++;
        for(int i=0;i<s.length();i++)if(cnt[s.charAt(i)-'a']<k){int j=i+1;while(j<s.length()&&cnt[s.charAt(j)-'a']<k)j++;return Math.max(longestSubstring(s.substring(0,i),k),longestSubstring(s.substring(j),k));}
        return s.length();
    }
}

class Solution:
    def maxRotateFunction(self, nums: list[int]) -> int:
        n=len(nums)
        if not n:return 0
        total=sum(nums);f=sum(i*x for i,x in enumerate(nums));best=f
        for k in range(1,n):
            f=f+total-n*nums[n-k];best=max(best,f)
        return best

class Solution {
    public int maxRotateFunction(int[] nums) {
        int n=nums.length;if(n==0)return 0;long total=0,f=0;
        for(int i=0;i<n;i++){total+=nums[i];f+=(long)i*nums[i];}long best=f;
        for(int k=1;k<n;k++){f=f+total-(long)n*nums[n-k];best=Math.max(best,f);}return (int)best;
    }
}

class Solution:
    def integerReplacement(self, n: int) -> int:
        steps=0
        while n!=1:
            if n%2==0:n//=2
            elif n==3 or n%4==1:n-=1
            else:n+=1
            steps+=1
        return steps

class Solution {
    public int integerReplacement(int n) {
        long x=n;int steps=0;
        while(x!=1){if((x&1)==0)x>>=1;else if(x==3||(x&3)==1)x--;else x++;steps++;}
        return steps;
    }
}
